pub fn case_7<F: WitnessField>(
    row: &[F],
    row_index: u64,
    hint: &WitnessData<F>,
    data: &WitnessData<F>,
) -> Vec<F> {
    let mut output: Vec<F> = Vec::with_capacity(9);
    output.push(hint.get("hint", 1, usize::try_from(0u64).unwrap_or(usize::MAX), 0));
    output.push(hint.get("hint", 1, usize::try_from(1u64).unwrap_or(usize::MAX), 0));
    output.push(hint.get(
        "hint",
        1,
        usize::try_from(safe_rem(row_index, 4u64)).unwrap_or(usize::MAX),
        0,
    ));
    output.push(hint.get(
        "hint",
        1,
        usize::try_from(18446744073709551615u64).unwrap_or(usize::MAX),
        0,
    ));
    output.push(hint.get("hint", 2, usize::try_from(0u64).unwrap_or(usize::MAX), 0));
    output.push(data.get("memory", 2, usize::try_from(0u64).unwrap_or(usize::MAX), 0));
    output.push(data.get(
        "memory",
        2,
        usize::try_from(safe_rem(row_index, 3u64)).unwrap_or(usize::MAX),
        1,
    ));
    output.push(data.get("memory", 3, usize::try_from(0u64).unwrap_or(usize::MAX), 0));
    output.push(data.get("missing", 2, usize::try_from(0u64).unwrap_or(usize::MAX), 0));
    output
}

pub fn eval_case<F: WitnessField>(
    case: usize,
    input: &[F],
    row: u64,
    hint: &WitnessData<F>,
    data: &WitnessData<F>,
) -> Vec<F> {
    match case {
        0 => case_0(input, row, hint, data),
        1 => case_1(input, row, hint, data),
        2 => case_2(input, row, hint, data),
        3 => case_3(input, row, hint, data),
        4 => case_4(input, row, hint, data),
        5 => case_5(input, row, hint, data),
        6 => case_6(input, row, hint, data),
        7 => case_7(input, row, hint, data),
        _ => unreachable!("invalid reference case"),
    }
}
